const distance=(a,b)=>Math.hypot(...a.map((x,i)=>x-b[i])),blend=(p,w)=>p[0].map((_,i)=>p.reduce((s,q,j)=>s+w[j]*q[i],0)),B=t=>[(1-t)**2,2*t*(1-t),t*t];
