async function checkChildMetricPanel(child){const source=await get();if(source.mass_properties.ok){assert.equal(await page.locator('#centroid').textContent(),source.mass_properties.centroid.map(x=>x.toFixed(3)).join(', '));assert.equal(await page.locator('#full-inertia').textContent(),source.mass_properties.inertia.map(row=>'['+row.map(x=>x.toFixed(3)).join(', ')+']').join(' · '));}assert.equal(await page.locator('#volume').textContent(),source.volume.toFixed(3));const mass=child?.mass_properties;if(!child){assert.equal(await page.locator('#child-centroid').textContent(),'—');assert.equal(await page.locator('#child-inertia').textContent(),'—');assert.equal(await page.locator('#child-full-inertia').textContent(),'—');return;}if(mass.ok){assert.equal(await page.locator('#child-centroid').textContent(),mass.centroid.map(x=>x.toFixed(3)).join(', '));assert.equal(await page.locator('#child-inertia').textContent(),mass.inertia.map((row,i)=>row[i].toFixed(3)).join(', '));assert.equal(await page.locator('#child-full-inertia').textContent(),mass.inertia.map(row=>'['+row.map(x=>x.toFixed(3)).join(', ')+']').join(' · '));assert.match(await page.locator('#child-mass-status').textContent(),/Actual selected child.*centroid reference.*world axes/);}else{assert.equal(await page.locator('#child-centroid').textContent(),'Unavailable');assert.equal(await page.locator('#child-full-inertia').textContent(),'Unavailable');assert.equal(await page.locator('#child-mass-status').textContent(),mass.error);}}
function checkChildMassConservation(result,source){const children=[result.lower,result.upper],metrics=children.map(c=>c.mass_properties);if(source.major_radius===16&&source.minor_radius===4)assert.ok(metrics.every(m=>m.ok),'ordinary torus child metrics are resolved');for(let i=0;i<2;i++){const m=metrics[i];assert.equal(typeof m.ok,'boolean');if(m.ok){assert.equal(m.reference,'centroid');assert.equal(m.tensor_axes,'world');assert.equal(m.volume_units,'mm^3');assert.equal(m.inertia_units,'mm^5');assert.ok(Math.abs(m.volume-children[i].volume)<1e-12*Math.max(1,m.volume));const expectedZ=(i===0?-1:1)*4*Math.PI*source.major_radius*(source.minor_radius**2-result.cut_height**2)**1.5/(3*m.volume),expected=world(source,[0,0,expectedZ]);assert.ok(distance(m.centroid,expected)<1e-8*Math.max(1,source.major_radius),'independent disk-segment first moment');}else assert.ok(typeof m.error==='string'&&m.error.length>0);}
if(metrics.every(m=>m.ok)&&source.mass_properties.ok){const volume=metrics.reduce((s,m)=>s+m.volume,0),center=metrics[0].centroid.map((_,i)=>metrics.reduce((s,m)=>s+m.volume*m.centroid[i],0)/volume);assert.ok(distance(center,source.mass_properties.centroid)<1e-8*Math.max(1,source.major_radius));const total=Array.from({length:3},(_,i)=>Array.from({length:3},(_,j)=>metrics.reduce((sum,m)=>{const d=m.centroid.map((x,k)=>x-source.mass_properties.centroid[k]),square=d.reduce((s,x)=>s+x*x,0);return sum+m.inertia[i][j]+m.volume*((i===j?square:0)-d[i]*d[j]);},0))),scale=Math.max(1,...source.mass_properties.inertia.flat().map(Math.abs));for(let i=0;i<3;i++)for(let j=0;j<3;j++)assert.ok(Math.abs(total[i][j]-source.mass_properties.inertia[i][j])<1e-9*scale,'full world parallel-axis mass conservation');}}
