function childSegmentParity(wasm,native){assert.deepEqual(Object.keys(wasm),Object.keys(native));assert.equal(wasm.hits.length,native.hits.length);const copies=[structuredClone(wasm),structuredClone(native)];wasm.hits.forEach((hit,i)=>{const other=native.hits[i];assert.deepEqual(Object.keys(hit.boundary),Object.keys(other.boundary));assert.ok(Object.hasOwn(hit.boundary,'distance')&&Object.hasOwn(other.boundary,'distance'));for(const h of [hit,other]){const d=h.boundary.distance;assert.ok(Number.isFinite(d)&&d>=0);const measured=distance(h.point,h.boundary.point);assert.ok(Math.abs(d-measured)<=32*Number.EPSILON*Math.max(Number.MIN_VALUE,d,measured),'reported child residual independently matches actual point pair');}const displacedHit=distance(hit.point,other.point),displacedWitness=distance(hit.boundary.point,other.boundary.point),reserve=32*Number.EPSILON*Math.max(Number.MIN_VALUE,hit.boundary.distance,other.boundary.distance);assert.ok(Math.abs(hit.boundary.distance-other.boundary.distance)<=displacedHit+displacedWitness+reserve,'child residual triangle inequality from actual coordinate displacement');for(const copy of copies)delete copy.hits[i].boundary.distance;});parity(copies[0],copies[1]);}
