async function sectionProbe(height,chord=.1,{native=true}={}){const before=await page.evaluate(()=>{const t=window.haganeNurbsTorus;return{data:t.data,cut:t.cut,query:t.query,segment:t.segment,line:t.line,ray:t.ray,child_query:t.child_query,child_segment:t.child_segment,child_line:t.child_line,child_ray:t.child_ray,preview:t.preview,step:t.step,child_step:t.child_step};}),camera=await page.locator('canvas').evaluate(c=>({...c.haganeCamera}));await page.locator('#section-height').fill(String(height));await page.locator('#section-chord').fill(String(chord));await page.locator('#section-source').click();const result=await page.evaluate(()=>window.haganeNurbsTorus.section);assert.equal(await page.evaluate(()=>window.haganeNurbsTorus.section_error),null);assert.ok(result);assert.equal(result.stock_unchanged,true);assert.equal(result.mesh_free,true);assert.equal(result.closed,true);assert.equal(result.cut_created,false);assert.equal(result.loops.length,2);assert.equal(result.curves.length,8);assert.equal(result.vertices.length,8);assert.deepEqual(await page.evaluate(()=>{const t=window.haganeNurbsTorus;return{data:t.data,cut:t.cut,query:t.query,segment:t.segment,line:t.line,ray:t.ray,child_query:t.child_query,child_segment:t.child_segment,child_line:t.child_line,child_ray:t.child_ray,preview:t.preview,step:t.step,child_step:t.child_step};}),before);assert.deepEqual(await page.locator('canvas').evaluate(c=>({...c.haganeCamera})),camera);const source=await get(),radial=Math.sqrt(source.minor_radius**2-height**2);for(let i=0;i<8;i++){const c=result.curves[i];assert.equal(c.points.length,c.parameters.length);assert.equal(c.error_bounds.length,c.points.length-1);assert.ok(c.error_bounds.every(e=>Number.isFinite(e)&&e<=chord));for(let j=0;j<c.points.length;j++){const p=local(source,c.points[j]);assert.ok(Math.abs(p[2]-height)<source.linear_tolerance/4);assert.ok(Math.abs(Math.hypot(p[0],p[1])-(source.major_radius+(i<4?radial:-radial)))<source.linear_tolerance/4);assert.ok(distance(curve(c.curve,c.parameters[j]),c.points[j])<source.linear_tolerance/4);}for(let j=0;j<c.error_bounds.length;j++){const t=(c.parameters[j]+c.parameters[j+1])/2,p=curve(c.curve,t),a=c.points[j],d=c.points[j+1].map((x,k)=>x-a[k]),f=Math.max(0,Math.min(1,p.reduce((sum,x,k)=>sum+(x-a[k])*d[k],0)/d.reduce((sum,x)=>sum+x*x,0))),q=a.map((x,k)=>x+f*d[k]);assert.ok(distance(p,q)<=c.error_bounds[j]+source.linear_tolerance/32);}for(const use of c.source_uses)for(const t of [0,.2,.7,1]){const uv=use.pcurve.origin.map((x,j)=>x+t*use.pcurve.direction[j]);assert.ok(distance(curve(c.curve,t),surface(source.brep.surfaces[use.face],...uv))<source.linear_tolerance/4);}}for(const [li,loop] of result.loops.entries()){assert.equal(loop.role,li===0?'outer':'inner');assert.equal(loop.coedges.length,4);assert.equal(loop.orientation,'increasing source major U');for(let i=0;i<4;i++){const a=result.curves[loop.coedges[i].edge],b=result.curves[loop.coedges[(i+1)%4].edge];assert.equal(a.vertices[1],b.vertices[0]);}}if(native){const values=await page.evaluate(()=>['major-radius','minor-radius','angle','tx','ty','tz','linear-tolerance','chord-error'].map(id=>document.getElementById(id).valueAsNumber));values[2]*=Math.PI/180;values[7]=chord;const n=spawnSync('cargo',['run','--quiet','--locked','--example','nurbs_torus_section',JSON.stringify([...values,height])],{cwd:new URL('..',import.meta.url),encoding:'utf8',maxBuffer:32*1024*1024});assert.equal(n.status,0,n.stderr);parity(result,JSON.parse(n.stdout));}return result;}
