function checkSlab(child,source,heights,chord){const cap=child.brep.faces-2,R=source.major_radius,r=source.minor_radius,counts=new Map();assert.equal(child.brep.closed,true);for(const id of [cap,cap+1]){assert.equal(child.brep.surfaces[id].kind,'plane');assert.equal(child.brep.wire_edges[id].length,2);}assert.equal(child.brep.vertices.length-child.brep.edges+child.brep.faces-2,0);for(let f=0;f<child.brep.faces;f++)for(let wi=0;wi<child.brep.wire_edges[f].length;wi++)for(let ci=0;ci<child.brep.wire_edges[f][wi].length;ci++){const id=child.brep.wire_edges[f][wi][ci],forward=child.brep.wire_forwards[f][wi][ci],c=child.brep.curves[id],pc=child.brep.wire_pcurves[f][wi][ci];if(f<cap&&pc.kind==='nurbs')assert.equal(pc.degree,1,'actual meridian UV uses retained linear NURBS endpoints');if(f>=cap){assert.equal(pc.kind,'nurbs');assert.equal(pc.degree,2);}counts.set(id,(counts.get(id)??0)+(forward?1:-1));for(let j=0;j<=8;j++){const t=j/8,uv=pc.kind==='nurbs'?rational(pc,t):pc.origin.map((x,k)=>x+t*pc.direction[k]);assert.ok(distance(rational(c,t),childSurface(child.brep.surfaces[f],uv[0],uv[1]))<1e-8*Math.max(1,R),'actual child edge/UV association');}}
assert.equal(counts.size,child.brep.edges);assert.ok([...counts.values()].every(x=>x===0));const nodes=new Map(),ids=child.mesh.positions.map(p=>{const key=p.join(',');if(!nodes.has(key))nodes.set(key,nodes.size);return nodes.get(key);}),edges=new Map();let volume=0;for(let ti=0;ti<child.mesh.triangles.length;ti++){const tri=child.mesh.triangles[ti],points=tri.map(i=>child.mesh.positions[i]),f=child.mesh.face_ids[ti];for(let k=0;k<3;k++){const a=ids[tri[k]],b=ids[tri[(k+1)%3]],key=Math.min(a,b)+','+Math.max(a,b),v=edges.get(key)??[0,0];assert.notEqual(a,b);v[0]++;v[1]+=a<b?1:-1;edges.set(key,v);}const q=points.map(p=>local(source,p));const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];const n=cross(q[1].map((x,i)=>x-q[0][i]),q[2].map((x,i)=>x-q[0][i]));assert.ok(Math.hypot(...n)>0);volume+=q[0].reduce((sum,x,i)=>sum+x*cross(q[1],q[2])[i],0)/6;
for(const weights of [[1/3,1/3,1/3],[.5,.25,.25],[.25,.5,.25],[.25,.25,.5]]){const point=blend(points,weights),x=local(source,point);if(f>=cap){const h=heights[f-cap],inner=R-Math.sqrt(r*r-h*h);assert.ok(Math.abs(x[2]-h)<source.linear_tolerance/4);assert.ok(Math.hypot(x[0],x[1])>=inner-chord,'slab annular cap chord intrusion bounded');assert.ok(n[2]*(f===cap?-1:1)>0);}else{const s=child.brep.surfaces[f],va=s.knots[1][2],vb=s.knots[1][3],start=local(source,childSurface(s,0,va)),a0=Math.atan2(start[1],start[0]),quarterStart=Math.atan2(start[2],Math.hypot(start[0],start[1])-R)-2*Math.atan(Math.SQRT1_2*va/(1-(1-Math.SQRT1_2)*va)),angles=q.map(p=>[angleDelta(Math.atan2(p[1],p[0]),a0),angleDelta(Math.atan2(p[2],Math.hypot(p[0],p[1])-R),quarterStart)]),ang=blend(angles,weights),inverse=a=>{const t=Math.tan(a/2);return t/(Math.SQRT1_2+(1-Math.SQRT1_2)*t);};assert.ok(distance(childSurface(s,Math.max(0,Math.min(1,inverse(ang[0]))),Math.max(va,Math.min(vb,inverse(ang[1])))),point)<=chord+1e-8*Math.max(1,R),'whole actual restricted wall angular triangle');}}
for(let k=0;k<3;k++){const p=q[k];assert.ok(p[2]>=heights[0]-source.linear_tolerance/4&&p[2]<=heights[1]+source.linear_tolerance/4);const rho=Math.hypot(p[0],p[1]),expected=f>=cap?source.placement.axes[2].map(x=>x*(f===cap?-1:1)):world({...source,placement:{...source.placement,translation:[0,0,0]}},[(rho-R)*p[0]/rho/r,(rho-R)*p[1]/rho/r,p[2]/r]);assert.ok(distance(expected,child.mesh.normals[tri[k]])<1e-7,'actual retained child outward normal');}}
assert.ok([...edges.values()].every(([n,d])=>n===2&&d===0));assert.equal(nodes.size-edges.size+child.mesh.triangles.length,0);assert.ok(volume>0);assert.ok(Math.abs(volume-child.volume)<child.volume*.05);assert.match(child.step,/RATIONAL_B_SPLINE_SURFACE/);assert.equal((child.step.match(/ADVANCED_FACE\(/g)??[]).length,child.brep.faces);}
